inline_styles:
/* SKKNI Detail Styling */
.skkni-header {
    background: linear-gradient(135deg, #0f172a 0%, #1e3a8a 60%, #1e40af 100%);
    color: #ffffff;
    padding: 48px 0 44px;
}
.skkni-breadcrumb {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 0.85rem;
    margin-bottom: 20px;
    flex-wrap: wrap;
}
.skkni-breadcrumb a {
    color: #93c5fd;
    text-decoration: none;
}
.skkni-breadcrumb a:hover {
    color: #ffffff;
    text-decoration: underline;
}
.skkni-breadcrumb span.sep {
    color: #64748b;
}
.skkni-breadcrumb span.current {
    color: #cbd5e1;
}

.skkni-badges {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 14px;
    flex-wrap: wrap;
}
.skkni-badge-tag {
    background: #0284c7;
    color: #ffffff;
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    padding: 4px 10px;
    border-radius: 6px;
    letter-spacing: 0.04em;
}
.skkni-badge-level {
    background: rgba(255, 255, 255, 0.15);
    border: 1px solid rgba(255, 255, 255, 0.25);
    color: #f8fafc;
    font-size: 0.78rem;
    font-weight: 600;
    padding: 4px 10px;
    border-radius: 6px;
}
.skkni-ref-no {
    font-size: 0.95rem;
    color: #38bdf8;
    font-weight: 600;
    margin-bottom: 8px;
}
.skkni-main-title {
    font-size: clamp(1.8rem, 3.2vw, 2.5rem);
    font-weight: 800;
    line-height: 1.25;
    margin: 0 0 16px;
}
.skkni-lead {
    font-size: 1.05rem;
    line-height: 1.65;
    color: #e2e8f0;
    max-width: 820px;
    margin: 0;
}

/* Detail Layout */
.skkni-body {
    padding: 50px 0 70px;
    background: #f8fafc;
}
.skkni-layout {
    display: grid;
    grid-template-columns: 1fr 340px;
    gap: 36px;
    align-items: start;
}
@media (max-width: 960px) {
    .skkni-layout {
        grid-template-columns: 1fr;
    }
}

/* Main Column Sections */
.skkni-section-card {
    background: #ffffff;
    border-radius: 14px;
    border: 1px solid #e2e8f0;
    padding: 32px;
    margin-bottom: 28px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.03);
}
.skkni-section-title {
    font-size: 1.35rem;
    font-weight: 700;
    color: #0f172a;
    margin: 0 0 18px;
    display: flex;
    align-items: center;
    gap: 10px;
    border-bottom: 2px solid #f1f5f9;
    padding-bottom: 12px;
}
.skkni-prose {
    font-size: 1rem;
    line-height: 1.75;
    color: #334155;
}
.skkni-prose p {
    margin: 0 0 18px;
}
.skkni-prose a {
    color: #1e40af;
    font-weight: 600;
    text-decoration: underline;
    text-underline-offset: 3px;
    transition: color 0.2s;
}
.skkni-prose a:hover {
    color: #1d4ed8;
}

/* Units Table */
.units-table-wrapper {
    overflow-x: auto;
    border: 1px solid #e2e8f0;
    border-radius: 10px;
}
.units-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.92rem;
    text-align: left;
}
.units-table th {
    background: #f1f5f9;
    color: #475569;
    font-weight: 700;
    padding: 12px 16px;
    border-bottom: 1px solid #e2e8f0;
}
.units-table td {
    padding: 12px 16px;
    border-bottom: 1px solid #f1f5f9;
    color: #334155;
}
.units-table tr:last-child td {
    border-bottom: none;
}
.units-table tr:hover {
    background: #f8fafc;
}
.unit-code {
    font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
    font-size: 0.85rem;
    font-weight: 600;
    color: #0369a1;
    white-space: nowrap;
}

/* Box info blocks */
.info-block {
    background: #f8fafc;
    border-left: 4px solid #1e40af;
    padding: 18px 20px;
    border-radius: 0 8px 8px 0;
    margin-bottom: 20px;
    font-size: 0.95rem;
    line-height: 1.65;
    color: #334155;
    white-space: pre-line;
}

/* Salary & Career Grid */
.career-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin-top: 10px;
}
@media (max-width: 640px) {
    .career-grid {
        grid-template-columns: 1fr;
    }
}
.career-box {
    background: #f0fdf4;
    border: 1px solid #bbf7d0;
    border-radius: 10px;
    padding: 20px;
}
.career-box-title {
    font-size: 0.88rem;
    font-weight: 700;
    text-transform: uppercase;
    color: #166534;
    margin-bottom: 8px;
    letter-spacing: 0.04em;
}
.career-box-val {
    font-size: 1.05rem;
    font-weight: 700;
    color: #14532d;
    line-height: 1.5;
}

/* FAQ Accordion UI */
.faq-item {
    background: #f8fafc;
    border: 1px solid #e2e8f0;
    border-radius: 10px;
    padding: 18px 20px;
    margin-bottom: 12px;
}
.faq-q {
    font-size: 1.02rem;
    font-weight: 700;
    color: #0f172a;
    margin: 0 0 8px;
}
.faq-a {
    font-size: 0.92rem;
    color: #475569;
    line-height: 1.65;
    margin: 0;
}

/* Sidebar Styling */
.skkni-sidebar {
    position: -webkit-sticky;
    position: sticky;
    top: 90px;
    align-self: start;
    height: fit-content;
    z-index: 30;
}
@media (max-width: 960px) {
    .skkni-sidebar {
        position: static;
        top: auto;
    }
}
.skkni-sidebar-card {
    background: #ffffff;
    border-radius: 14px;
    border: 1px solid #e2e8f0;
    padding: 24px;
    margin-bottom: 24px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.03);
}
.skkni-sidebar-title {
    font-size: 1.1rem;
    font-weight: 700;
    color: #0f172a;
    margin: 0 0 16px;
    padding-bottom: 10px;
    border-bottom: 1px solid #f1f5f9;
}
.fact-row {
    display: flex;
    justify-content: space-between;
    padding: 10px 0;
    border-bottom: 1px dashed #f1f5f9;
    font-size: 0.88rem;
}
.fact-row:last-child {
    border-bottom: none;
}
.fact-label {
    color: #64748b;
}
.fact-val {
    font-weight: 600;
    color: #0f172a;
    text-align: right;
    max-width: 60%;
}

.wa-btn-card {
    display: block;
    background: #22c55e;
    color: #ffffff;
    text-align: center;
    padding: 14px 20px;
    border-radius: 10px;
    font-weight: 700;
    font-size: 0.95rem;
    text-decoration: none;
    transition: background 0.2s;
    box-shadow: 0 4px 12px rgba(34, 197, 94, 0.25);
}
.wa-btn-card:hover {
    background: #16a34a;
}

/* Related items list */
.related-item {
    display: block;
    padding: 12px 0;
    border-bottom: 1px solid #f1f5f9;
    text-decoration: none;
}
.related-item:last-child {
    border-bottom: none;
}
.related-item-title {
    font-size: 0.92rem;
    font-weight: 600;
    color: #1e293b;
    margin-bottom: 4px;
    transition: color 0.2s;
}
.related-item:hover .related-item-title {
    color: #1e40af;
}
.related-item-sub {
    font-size: 0.78rem;
    color: #64748b;
}
